import sys

def main():
    data = sys.stdin.buffer.read()
    lines = data.split(b'\n')
    # First line is header, skip it
    if len(lines) > 1:
        # Remove trailing empty element if file ends with newline
        if lines[-1] == b'':
            lines.pop()
    else:
        lines = []

    counts = {}
    sums = {}

    for line in lines[1:]:
        if not line:
            continue
        comma_idx = line.find(b',')
        key = line[:comma_idx]
        val_str = line[comma_idx+1:]
        val = int(val_str)

        if key in counts:
            counts[key] += 1
            sums[key] += val
        else:
            counts[key] = 1
            sums[key] = val

    out_lines = [b'key,count,sum']
    for key in sorted(counts):
        out_lines.append(key + b',' + str(counts[key]).encode() + b',' + str(sums[key]).encode())

    sys.stdout.buffer.write(b'\n'.join(out_lines) + b'\n')

if __name__ == '__main__':
    main()

