    for key, value in zip(fields, fields):
        record = get(key)
        if record is None:
            aggregates[key] = [1, int(value)]
        else:
            record[0] += 1
            record[1] += int(value)

    output = ['key,count,sum\n']
    for key in sorted(aggregates):
        count, total = aggregates[key]
